import "server-only";
import fs from "node:fs/promises";
import path from "node:path";
import { prisma, letterPlaqueFile } from "@lifeweb/db";

// A character's face as an image response: their uploaded picture, or the
// letter plaque for their FIRST name (never the honorific or the GM-granted
// title). Shared by /api/avatar/<id> and the two routes that serve a stranger's
// face without an id ever reaching the browser (docs/systemdocs/STRANGERS.md).
//
// The plaques are generated by web/scripts/generate-letters.js
// (`npm run assets:letters --workspace=web`) and committed. Which tile a name
// maps to is decided by letterPlaqueFile in db/lib/presentedIdentity.js, shared
// with the bot so a forced identity ("Beast") points at the same B tile.
const LETTERS_DIR = path.join(process.cwd(), "public/assets/letters");
const plateCache = new Map();

function readPlate(file) {
  if (!plateCache.has(file)) {
    // Cache the promise, not the buffer, so concurrent requests for the same
    // letter share one read.
    plateCache.set(
      file,
      fs.readFile(path.join(LETTERS_DIR, file)).catch((err) => {
        plateCache.delete(file);
        throw err;
      }),
    );
  }
  return plateCache.get(file);
}

// `cacheControl` is the caller's: the id route is public and immutable (every
// caller appends ?v=), while a stranger's face is per reader and short-lived.
//
// `blankPlaque` is for a stranger. With no uploaded portrait the default face
// is the first letter of their name, and handing a stranger's initial to
// somebody who cannot name them gives away the start of the name. They get
// the blank plaque instead.
export async function avatarResponse(characterId, { cacheControl, blankPlaque = false }) {
  const character = characterId
    ? await prisma.character.findUnique({
        where: { id: characterId },
        select: { avatarData: true, avatarMimeType: true, firstName: true },
      })
    : null;
  if (!character) return new Response("Not found", { status: 404 });

  let data = character.avatarData;
  let contentType = character.avatarMimeType ?? "application/octet-stream";

  if (!data) {
    try {
      data = await readPlate(blankPlaque ? "_default.webp" : letterPlaqueFile(character.firstName));
      contentType = "image/webp";
    } catch (err) {
      console.error(`Missing letter plaque for character ${characterId}:`, err);
      return new Response("Not found", { status: 404 });
    }
  }

  return new Response(data, { headers: { "Content-Type": contentType, "Cache-Control": cacheControl } });
}

// A stranger's face: private to the reader, and short-lived, because what the
// handle names changes when they move.
export const STRANGER_FACE_CACHE = "private, max-age=300";
